CREATE TABLE IF NOT EXISTS sessions(id text PRIMARY KEY,user_id text NOT NULL REFERENCES users(id) ON DELETE CASCADE,token_hash text NOT NULL UNIQUE,csrf_token text NOT NULL,expires_at timestamptz NOT NULL,revoked_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS sessions_user_idx ON sessions(user_id);
CREATE TABLE IF NOT EXISTS runner_registrations(id text PRIMARY KEY,workspace_id text NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,name text NOT NULL,credential_hash text NOT NULL UNIQUE,version text NOT NULL,capabilities_json jsonb NOT NULL,last_heartbeat_at timestamptz,revoked_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS runner_workspace_idx ON runner_registrations(workspace_id,revoked_at,last_heartbeat_at DESC);
CREATE TABLE IF NOT EXISTS verification_jobs(id text PRIMARY KEY,workspace_id text NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,run_id text NOT NULL REFERENCES runs(id) ON DELETE CASCADE UNIQUE,actor_id text NOT NULL,status text NOT NULL CHECK(status IN ('QUEUED','CLAIMED','RUNNING','WAITING_RUNNER','COMPLETED','FAILED','CANCELLED')),attempt integer NOT NULL DEFAULT 0,max_attempts integer NOT NULL DEFAULT 5,available_at timestamptz NOT NULL DEFAULT now(),claimed_by text,claim_expires_at timestamptz,last_heartbeat_at timestamptz,error_code text,error_message text,request_key text,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(workspace_id,request_key));
CREATE INDEX IF NOT EXISTS verification_jobs_claim_idx ON verification_jobs(status,available_at,claim_expires_at);
CREATE TABLE IF NOT EXISTS runner_jobs(id text PRIMARY KEY,workspace_id text NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,verification_job_id text NOT NULL REFERENCES verification_jobs(id) ON DELETE CASCADE,run_id text NOT NULL REFERENCES runs(id) ON DELETE CASCADE,check_id text NOT NULL REFERENCES verification_checks(id) ON DELETE CASCADE,criterion_id text NOT NULL,type text NOT NULL,required_capability text,payload_json jsonb NOT NULL,status text NOT NULL CHECK(status IN ('QUEUED','LEASED','RUNNING','COMPLETED','FAILED','CANCELLED','TIMED_OUT')),runner_id text REFERENCES runner_registrations(id),lease_token_hash text,lease_expires_at timestamptz,attempt integer NOT NULL DEFAULT 0,max_attempts integer NOT NULL DEFAULT 3,available_at timestamptz NOT NULL DEFAULT now(),result_json jsonb,error_json jsonb,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(verification_job_id,criterion_id));
CREATE INDEX IF NOT EXISTS runner_jobs_claim_idx ON runner_jobs(workspace_id,status,available_at,lease_expires_at);
CREATE INDEX IF NOT EXISTS runner_jobs_verification_idx ON runner_jobs(verification_job_id,created_at);
CREATE TABLE IF NOT EXISTS integrations(id text PRIMARY KEY,workspace_id text NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,kind text NOT NULL,external_id text,config_encrypted text,status text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(workspace_id,kind,external_id));
CREATE TABLE IF NOT EXISTS webhook_deliveries(id text PRIMARY KEY,workspace_id text,provider text NOT NULL,external_delivery_id text NOT NULL,event_type text NOT NULL,payload_hash text NOT NULL,status text NOT NULL,attempts integer NOT NULL DEFAULT 0,last_error text,received_at timestamptz NOT NULL DEFAULT now(),processed_at timestamptz,UNIQUE(provider,external_delivery_id));
CREATE TABLE IF NOT EXISTS usage_events(id text PRIMARY KEY,workspace_id text NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,event_name text NOT NULL,actor_id text,resource_id text,metadata_json jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS usage_workspace_idx ON usage_events(workspace_id,created_at DESC);
